```tsx
import "./AlertBanner.css";

export interface AlertBannerProps {
  message: string;
  onRetry: () => void;
}

export function AlertBanner({ message, onRetry }: AlertBannerProps) {
  return (
    <div className="alert-banner" role="alert">
      <span className="alert-banner__icon" aria-hidden="true">!</span>
      <p className="alert-banner__message">{message}</p>
      <button
        type="button"
        className="alert-banner__button"
        onClick={onRetry}
      >
        Retry
      </button>
    </div>
  );
}
```

```css
/*
 * AlertBanner styles.
 * Colors are driven by custom properties. Day is the default. Night applies
 * when an ancestor (typically <html>) carries data-theme="night".
 */

:root {
  --alert-banner-bg: #fdf1e3;
  --alert-banner-border: #d9822b;
  --alert-banner-text: #3d2a14;
  --alert-banner-icon-bg: #d9822b;
  --alert-banner-icon-text: #ffffff;
  --alert-banner-button-bg: #3d2a14;
  --alert-banner-button-text: #fdf1e3;
  --alert-banner-button-hover: #5a3f1f;
  --alert-banner-focus: #1f5fbf;
}

[data-theme="night"] {
  --alert-banner-bg: #2a2118;
  --alert-banner-border: #e0a052;
  --alert-banner-text: #f3e7d6;
  --alert-banner-icon-bg: #e0a052;
  --alert-banner-icon-text: #1d160f;
  --alert-banner-button-bg: #f3e7d6;
  --alert-banner-button-text: #1d160f;
  --alert-banner-button-hover: #ffffff;
  --alert-banner-focus: #8ab8ff;
}

.alert-banner {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  width: 100%;
  box-sizing: border-box;
  padding: 0.75rem 1rem;
  border-left: 4px solid var(--alert-banner-border);
  border-radius: 6px;
  background-color: var(--alert-banner-bg);
  color: var(--alert-banner-text);
  font-family: inherit;
  font-size: 0.95rem;
  line-height: 1.4;
}

.alert-banner__icon {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 50%;
  background-color: var(--alert-banner-icon-bg);
  color: var(--alert-banner-icon-text);
  font-weight: 700;
  font-size: 0.9rem;
}

.alert-banner__message {
  flex: 1 1 auto;
  margin: 0;
  min-width: 0;
  overflow-wrap: anywhere;
}

.alert-banner__button {
  flex: 0 0 auto;
  margin: 0;
  padding: 0.4rem 0.9rem;
  border: 2px solid transparent;
  border-radius: 4px;
  background-color: var(--alert-banner-button-bg);
  color: var(--alert-banner-button-text);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.alert-banner__button:hover {
  background-color: var(--alert-banner-button-hover);
}

.alert-banner__button:active {
  transform: translateY(1px);
}

.alert-banner__button:focus {
  outline: none;
}

.alert-banner__button:focus-visible {
  outline: 3px solid var(--alert-banner-focus);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .alert-banner__button:active {
    transform: none;
  }
}

@media (max-width: 480px) {
  .alert-banner {
    flex-wrap: wrap;
  }

  .alert-banner__message {
    flex-basis: calc(100% - 2.25rem);
  }

  .alert-banner__button {
    margin-left: 2.25rem;
  }
}
```

